"""Capstone: the same small maze solved by five methods from the subject, with identical budgets.

Maze 6x9 (walls), start (2,0), goal (0,8), reward +1 at the goal, gamma 0.95, eps-greedy 0.1, 30 episodes.
Reports the mean episode length over episodes 21-30 (shortest possible: 14) averaged over 10 seeds.
"""
import numpy as np
R_, C_ = 6, 9; WALLS = {(1, 2), (2, 2), (3, 2), (4, 5), (0, 7), (1, 7), (2, 7)}; S0, G = (2, 0), (0, 8)
MV = [(-1, 0), (0, 1), (1, 0), (0, -1)]
def step(s, a):
    r, c = s[0] + MV[a][0], s[1] + MV[a][1]
    if not (0 <= r < R_ and 0 <= c < C_) or (r, c) in WALLS: r, c = s
    return (r, c), float((r, c) == G)
def egreedy(Q, s, rng, eps=0.1):
    return int(rng.integers(4)) if rng.random() < eps else int(np.argmax(Q[s] + rng.random(4) * 1e-9))
def run(method, seed, episodes=30, alpha=0.5, gamma=0.95):
    rng = np.random.default_rng(seed); Q = np.zeros((R_, C_, 4)); N = np.zeros((R_, C_, 4)); model = {}; lens = []
    for _ in range(episodes):
        s, a, traj = S0, None, []
        a = egreedy(Q, s, rng)
        while s != G and len(traj) < 5000:
            s2, r = step(s, a); a2 = egreedy(Q, s2, rng); traj.append((s, a, r)); done = s2 == G
            if method == "Q-learning": tgt = r + (0 if done else gamma * Q[s2].max())
            elif method == "SARSA": tgt = r + (0 if done else gamma * Q[s2][a2])
            elif method == "Expected SARSA":
                p = np.full(4, 0.025); p[int(np.argmax(Q[s2]))] += 0.9; tgt = r + (0 if done else gamma * p @ Q[s2])
            elif method == "Dyna-Q (n=10)": tgt = r + (0 if done else gamma * Q[s2].max())
            if method != "MC control": Q[s][a] += alpha * (tgt - Q[s][a])
            if method == "Dyna-Q (n=10)":
                model[(s, a)] = (r, s2); keys = list(model)
                for _ in range(10):
                    ps, pa = keys[rng.integers(len(keys))]; pr, ps2 = model[(ps, pa)]
                    Q[ps][pa] += alpha * (pr + (0 if ps2 == G else gamma * Q[ps2].max()) - Q[ps][pa])
            s, a = s2, a2
        if method == "MC control":
            Gr, seen = 0.0, {}
            for (st, ac, r) in reversed(traj): Gr = r + gamma * Gr; seen[(st, ac)] = Gr
            for (st, ac), Gv in seen.items(): N[st][ac] += 1; Q[st][ac] += (Gv - Q[st][ac]) / N[st][ac]
        lens.append(len(traj))
    return np.mean(lens[20:])
for m in ("MC control", "SARSA", "Expected SARSA", "Q-learning", "Dyna-Q (n=10)"):
    print(f"{m:<16} mean steps, episodes 21-30: {np.mean([run(m, s) for s in range(10)]):7.1f}")
